from pathlib import Path

ROOT = Path('.')


def read(path):
    return (ROOT / path).read_text(encoding='utf-8')


def write(path, text):
    (ROOT / path).write_text(text, encoding='utf-8')


def replace_once(path, old, new):
    text = read(path)
    if new in text:
        return
    if old not in text:
        raise RuntimeError(f'V16 anchor not found in {path}: {old[:160]!r}')
    write(path, text.replace(old, new, 1))


# 1) python_execute: expose a bounded, read-only filesystem-probe subset through
# os.path. Relative paths are rooted in OUTPUT_DIR. Arbitrary Android/system
# paths remain unprobeable unless explicitly supplied by the user.
old_facade = '''class _SafePathFacade:\n    \"\"\"Pure path-string operations only; no filesystem probing or process APIs.\"\"\"\n    join = staticmethod(_os.path.join)\n    basename = staticmethod(_os.path.basename)\n    dirname = staticmethod(_os.path.dirname)\n    split = staticmethod(_os.path.split)\n    splitext = staticmethod(_os.path.splitext)\n    normpath = staticmethod(_os.path.normpath)\n    isabs = staticmethod(_os.path.isabs)\n    commonpath = staticmethod(_os.path.commonpath)\n    commonprefix = staticmethod(_os.path.commonprefix)\n    relpath = staticmethod(_os.path.relpath)\n'''
new_facade = '''class _SafePathFacade:\n    \"\"\"Safe path-string helpers plus scoped read-only filesystem probes.\"\"\"\n    join = staticmethod(_os.path.join)\n    basename = staticmethod(_os.path.basename)\n    dirname = staticmethod(_os.path.dirname)\n    split = staticmethod(_os.path.split)\n    splitext = staticmethod(_os.path.splitext)\n    normpath = staticmethod(_os.path.normpath)\n    isabs = staticmethod(_os.path.isabs)\n    commonpath = staticmethod(_os.path.commonpath)\n    commonprefix = staticmethod(_os.path.commonprefix)\n    relpath = staticmethod(_os.path.relpath)\n\n    @staticmethod\n    def exists(path):\n        return SafeBuiltins._safe_path_probe(path, 'exists')\n\n    @staticmethod\n    def isfile(path):\n        return SafeBuiltins._safe_path_probe(path, 'isfile')\n\n    @staticmethod\n    def isdir(path):\n        return SafeBuiltins._safe_path_probe(path, 'isdir')\n\n    @staticmethod\n    def getsize(path):\n        return SafeBuiltins._safe_path_probe(path, 'getsize')\n\n    @staticmethod\n    def getmtime(path):\n        return SafeBuiltins._safe_path_probe(path, 'getmtime')\n'''
replace_once('python/navixmind/tools/code_executor.py', old_facade, new_facade)

safe_open_anchor = '''    @classmethod\n    def _safe_open(cls, file, mode='r', *args, **kwargs):\n        \"\"\"Allow user-provided inputs plus files created under OUTPUT_DIR.\"\"\"\n'''
safe_probe_block = '''    @classmethod\n    def _resolve_scoped_probe_path(cls, file):\n        \"\"\"Resolve a probe target without exposing arbitrary filesystem state.\"\"\"\n        raw = str(file)\n        if _os.path.isabs(raw):\n            candidate = _os.path.realpath(raw)\n        else:\n            # A sandboxed relative path is a workspace-relative path, never a\n            # process-CWD escape hatch.\n            base = cls._output_dir or '.'\n            candidate = _os.path.realpath(_os.path.join(base, raw))\n\n        def within(candidate_path: str, root: str) -> bool:\n            if not root:\n                return False\n            root_real = _os.path.realpath(str(root))\n            try:\n                return _os.path.commonpath([candidate_path, root_real]) == root_real\n            except ValueError:\n                return False\n\n        if cls._output_dir and within(candidate, cls._output_dir):\n            return candidate\n\n        for allowed in cls._allowed_paths:\n            allowed_real = _os.path.realpath(str(allowed))\n            if candidate == allowed_real:\n                return candidate\n            # A user-provided directory intentionally grants read-only access to\n            # descendants, matching safe_open's existing contract.\n            if _os.path.isdir(str(allowed)) and within(candidate, str(allowed)):\n                return candidate\n\n        raise SecurityError(\n            f\"Filesystem probing for '{file}' is not allowed. Only user-provided \"\n            \"paths and paths inside OUTPUT_DIR may be inspected.\"\n        )\n\n    @classmethod\n    def _safe_path_probe(cls, file, operation):\n        candidate = cls._resolve_scoped_probe_path(file)\n        allowed_ops = {'exists', 'isfile', 'isdir', 'getsize', 'getmtime'}\n        if operation not in allowed_ops:\n            raise SecurityError(f\"os.path operation '{operation}' is not allowed\")\n        return getattr(_os.path, operation)(candidate)\n\n    @classmethod\n    def _safe_open(cls, file, mode='r', *args, **kwargs):\n        \"\"\"Allow user-provided inputs plus files created under OUTPUT_DIR.\"\"\"\n'''
replace_once('python/navixmind/tools/code_executor.py', safe_open_anchor, safe_probe_block)

# 2) create_xlsx: normalize all model-facing sheet/row spellings into an exact
# 2-D matrix, then reopen the workbook and verify every written value. This
# fixes silent files where object wrappers became a literal 'item' cell.
old_xlsx = '''def create_xlsx(\n    output_path: str,\n    sheets: Optional[List[Dict[str, Any]]] = None,\n) -> dict:\n    \"\"\"Create an XLSX workbook from structured rows.\"\"\"\n    from openpyxl import Workbook\n\n    _ensure_parent(output_path)\n    wb = Workbook()\n    default = wb.active\n    configured = sheets or [{\"name\": \"Sheet1\", \"rows\": []}]\n    for i, spec in enumerate(configured):\n        ws = default if i == 0 else wb.create_sheet()\n        ws.title = str(spec.get(\"name\") or f\"Sheet{i + 1}\")[:31]\n        for row in spec.get(\"rows\", []) or []:\n            ws.append(list(row) if isinstance(row, (list, tuple)) else [row])\n    wb.save(output_path)\n    return {\"success\": True, \"output_path\": output_path, \"sheet_names\": wb.sheetnames}\n'''
new_xlsx = '''def create_xlsx(\n    output_path: str,\n    sheets: Optional[List[Dict[str, Any]]] = None,\n) -> dict:\n    \"\"\"Create XLSX from canonical or compatibility row structures, with verification.\"\"\"\n    import json\n    from openpyxl import Workbook, load_workbook\n\n    def scalar(value):\n        if value is None or isinstance(value, (str, int, float, bool)):\n            return value\n        return json.dumps(value, ensure_ascii=False, sort_keys=False)\n\n    def normalize_rows(spec):\n        raw = spec.get('rows')\n        if raw is None:\n            raw = spec.get('data')\n        if raw is None:\n            return []\n        if isinstance(raw, tuple):\n            raw = list(raw)\n        if not isinstance(raw, list):\n            raise ToolError('create_xlsx sheet rows/data must be an array')\n\n        # A list of ordinary objects is a record set: write deterministic\n        # headers once, then one value row per object.\n        if raw and all(isinstance(row, dict) and not (len(row) == 1 and 'item' in row) for row in raw):\n            headers = []\n            for row in raw:\n                for key in row.keys():\n                    key = str(key)\n                    if key not in headers:\n                        headers.append(key)\n            return [headers] + [[scalar(row.get(key)) for key in headers] for row in raw]\n\n        matrix = []\n        for row in raw:\n            # Compatibility adapters and some models emit {\"item\": [...]}\n            # for an array item. Unwrap it instead of writing the key itself.\n            if isinstance(row, dict) and len(row) == 1 and 'item' in row:\n                row = row['item']\n            if isinstance(row, (list, tuple)):\n                matrix.append([scalar(value) for value in row])\n            elif isinstance(row, dict):\n                matrix.append([scalar(value) for value in row.values()])\n            else:\n                matrix.append([scalar(row)])\n        return matrix\n\n    _ensure_parent(output_path)\n    configured = sheets or [{\"name\": \"Sheet1\", \"rows\": []}]\n    if not isinstance(configured, list) or not all(isinstance(spec, dict) for spec in configured):\n        raise ToolError('create_xlsx sheets must be an array of objects')\n\n    wb = Workbook()\n    default = wb.active\n    expected = {}\n    for i, spec in enumerate(configured):\n        ws = default if i == 0 else wb.create_sheet()\n        ws.title = str(spec.get('name') or spec.get('sheet_name') or f\"Sheet{i + 1}\")[:31]\n        matrix = normalize_rows(spec)\n        expected[ws.title] = matrix\n        for row in matrix:\n            ws.append(row)\n    wb.save(output_path)\n    wb.close()\n\n    check = load_workbook(output_path, data_only=False)\n    try:\n        for sheet_name, matrix in expected.items():\n            ws = check[sheet_name]\n            for r, row in enumerate(matrix, start=1):\n                for c, value in enumerate(row, start=1):\n                    actual = ws.cell(row=r, column=c).value\n                    if actual != value:\n                        raise ToolError(\n                            f\"XLSX verification failed at {sheet_name}!{ws.cell(r, c).coordinate}: \"\n                            f\"expected {value!r}, got {actual!r}\"\n                        )\n    finally:\n        check.close()\n\n    return {\n        \"success\": True,\n        \"output_path\": output_path,\n        \"sheet_names\": list(expected.keys()),\n        \"row_counts\": {name: len(rows) for name, rows in expected.items()},\n        \"verified\": True,\n    }\n'''
replace_once('python/navixmind/tools/extended_tools.py', old_xlsx, new_xlsx)

replace_once(
    'python/navixmind/tools/__init__.py',
    '\"sheets\": {\"type\": \"array\", \"items\": {\"type\": \"object\"}, \"description\": \"[{name, rows:[[...], ...]}]\"},',
    '\"sheets\": {\"type\": \"array\", \"items\": {\"type\": \"object\"}, \"description\": \"Sheets accept {name, rows:[[...]]}; compatibility aliases {sheet_name, data} are also accepted. Object rows become a header row plus records.\"},',
)

# 3) download_media: if Android native loading still fails, surface the exact
# runtime cause. The companion library is packaged separately by the V16 native
# preparer, so this is a diagnostic fallback, not the primary fix.
replace_once(
    'python/navixmind/tools/media.py',
    '''            try:\n                from curl_cffi import requests as browser_requests\n            except ImportError as exc:\n                raise ToolError(\n                    \"Browser impersonation runtime is unavailable; curl-cffi must be bundled \"\n                    \"for download_media.\"\n                ) from exc''',
    '''            try:\n                from curl_cffi import requests as browser_requests\n            except (ImportError, OSError) as exc:\n                detail = str(exc)\n                if 'libc++_shared' in detail or 'dlopen' in detail.lower():\n                    raise ToolError(\n                        \"Browser impersonation native runtime is incomplete: \" + detail\n                    ) from exc\n                raise ToolError(\n                    \"Browser impersonation runtime is unavailable; curl-cffi must be bundled \"\n                    \"for download_media.\"\n                ) from exc''',
)

print('V16 residual tool hardening patch applied.')
